/* ASCII-only local page; no third-party assets, cloud fetches or storage. */
static const char CP_SETUP_HEAD[] =
"<!doctype html><html lang=en><meta charset=utf-8><meta name=viewport content='width=device-width,initial-scale=1'><title>CampusPulse local setup</title>"
"<style>body{font:17px system-ui;max-width:35rem;margin:2rem auto;padding:1rem;background:#f4f7fa;color:#102437}label{display:block;margin:1rem 0}input,textarea,button{box-sizing:border-box;width:100%;padding:.8rem;font:inherit}button{background:#075e64;color:white;border:0}pre{white-space:pre-wrap}</style>"
"<h1>CampusPulse local setup</h1><p>Factory node: <strong id=node>";
static const char CP_SETUP_MID[] =
"</strong></p><p>This page runs on your device. Keep connected to its password-protected Wi-Fi. The PIN expires in 5 minutes; 5 failed attempts lock this session. Target networks may use WPA2 personal, open Wi-Fi, or PEAP/MSCHAPv2 enterprise authentication. Enterprise server certificates are not checked; cloud HTTPS certificates are still verified. Captive-portal login is not automatic.</p>"
"<form id=f autocomplete=off><label>8-digit setup PIN shown on device<input name=proof type=password inputmode=numeric required minlength=8 maxlength=8 pattern='[0-9]{8}' autocomplete=off></label>"
"<label>Cloud enrollment handoff from the administrator page<textarea name=handoff rows=5 required spellcheck=false autocomplete=off></textarea></label>"
"<label>Wi-Fi authentication<select name=security id=netmode><option value=wpa2>WPA2 personal</option><option value=open>Open network (no password)</option><option value=enterprise>Enterprise PEAP/MSCHAPv2 (no certificate check)</option></select></label><label>Target Wi-Fi SSID<input name=ssid required maxlength=32 autocomplete=off></label>"
"<div id=personal><label>Target Wi-Fi password<input name=password type=password required minlength=8 maxlength=63 autocomplete=new-password></label></div><div id=enterprise hidden><label>Enterprise username<input name=eap_username maxlength=128 autocomplete=off></label><label>Outer identity (optional)<input name=eap_identity maxlength=128 autocomplete=off></label><label>Enterprise password<input name=eap_password type=password minlength=1 maxlength=128 autocomplete=new-password></label></div>"
"<button>Submit to this device</button></form><pre id=status role=status></pre>"
"<script>const nonce='";
static const char CP_SETUP_END[] =
"';const mode=document.querySelector('#netmode'),form=document.querySelector('#f');mode.onchange=()=>{const enterprise=mode.value==='enterprise';document.querySelector('#personal').hidden=mode.value!=='wpa2';document.querySelector('#enterprise').hidden=!enterprise;form.password.required=mode.value==='wpa2';form.eap_username.required=enterprise;form.eap_password.required=enterprise;form.password.value='';form.eap_password.value='';};let busy=false;document.querySelector('#f').onsubmit=async(e)=>{e.preventDefault();if(busy)return;const f=e.target,s=document.querySelector('#status');let h;try{h=JSON.parse(f.handoff.value);if(h.v!==1||h.node_id!==document.querySelector('#node').textContent||!((h.reuse_saved_credential===true&&!Object.hasOwn(h,'device_token'))||(!Object.hasOwn(h,'reuse_saved_credential')&&/^cpd_[a-f0-9]{64}$/.test(h.device_token)))||!/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/.test(h.attempt_id))throw Error();}catch{s.textContent='Invalid handoff or wrong factory node. Return to the administrator page.';return;}busy=true;f.querySelector('button').disabled=true;s.textContent='Sending candidate settings...';try{const r=await fetch('/configure',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({v:1,op:'configure',nonce,proof:f.proof.value,node_id:h.node_id,...(h.reuse_saved_credential===true?{reuse_saved_credential:true}:{device_token:h.device_token}),attempt_id:h.attempt_id,ssid:f.ssid.value,wifi_security:f.security.value,password:f.security.value==='wpa2'?f.password.value:'',...(f.security.value==='enterprise'?{eap_username:f.eap_username.value,eap_password:f.eap_password.value,...(f.eap_identity.value?{eap_identity:f.eap_identity.value}:{})}:{})})});const a=await r.json();if(!a.ok)throw Error(a.reason||'Device rejected settings');f.reset();s.textContent='Received by device; network validation is still pending. The setup hotspot will stop. Check the device screen and reconnect to your normal network, then return to the administrator page to check cloud contact and configuration ACK.';}catch(error){busy=false;f.querySelector('button').disabled=false;const messages={saved_credential_unavailable:'No saved device credential is available. Return to the administrator page and provide the device credential.',invalid_credential_mode:'Choose either a saved credential or an explicit credential, never both.',invalid_setup_pin:'The setup PIN or local session is invalid. Check the screen and reload this local page.',setup_locked:'This setup session is locked. Start a new setup session on the device.'};s.textContent=messages[error.message]||'No confirmation received. Check the device screen and cloud status before retrying. Do not rotate the cloud credential merely because this response was lost.';}finally{h=null;}};window.addEventListener('pagehide',()=>document.querySelector('#f').reset());</script></html>";
